package com.opensocket.aievent.database.persistence.a2a.repository;
import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AParentAggregationRepository implements A2AParentAggregationRepository { private final A2AParentAggregationDao dao; private final A2APersistenceConverter c; public MybatisA2AParentAggregationRepository(A2AParentAggregationDao d,A2APersistenceConverter c){dao=d;this.c=c;} public A2AParentAggregation save(A2AParentAggregation v){dao.upsert(c.toPo(v));return findByParentTask(v.getTenantId(),v.getParentTaskId()).orElse(v);} public A2AParentAggregation saveExpectedVersion(A2AParentAggregation v,long expected){if(dao.updateExpectedVersion(c.toPo(v),expected)!=1)throw new IllegalStateException("RESOURCE_VERSION_CONFLICT");return findByParentTask(v.getTenantId(),v.getParentTaskId()).orElseThrow();} public Optional<A2AParentAggregation> findByParentTask(String t,String id){return Optional.ofNullable(dao.findByParentTask(t,id)).map(c::toDomain);} public String mode(){return "MYBATIS";} }
